mapper.select:
SELECT sku_id FROM customer_sku_visibility WHERE customer_id=#{customerId}
        AND deleted=FALSE AND sku_id IN
        #{id}

mapper.update:
UPDATE customer_sku_visibility
                            SET deleted= TRUE,
                                version=version + 1,
                                updated_at=CURRENT_TIMESTAMP,
                                updated_by=#{operator}
                            WHERE id = #{id}
                              AND version = #{version}
                              AND customer_id = #{customerId}
                              AND deleted = FALSE

mapper.select:
SELECT c.id customer_id,c.customer_code,c.name customer_name,t.name
customer_type_name,c.visibility_policy,v.sku_id,s.sku_code,p.name product_name,s.spec_name,s.status
sku_status,p.status spu_status,v.created_at,v.created_by
FROM customer c LEFT JOIN customer_type t ON t.id=c.customer_type_id
LEFT JOIN customer_sku_visibility v ON v.customer_id=c.id AND v.deleted=FALSE
LEFT JOIN product_sku s ON s.id=v.sku_id LEFT JOIN product_spu p ON p.id=s.spu_id WHERE c.deleted=FALSE
AND c.id=#{query.customerId}
AND v.sku_id=#{query.skuId}
AND c.visibility_policy=#{query.visibilityPolicy}
ORDER BY c.customer_code,v.id
